var i=`1058-roti-canai`;var a=`world-1058`;var o=`MY`;var n=`southeast-asia`;var r=8;var s=67;var l={en:`Roti Canai`,ua:`Роті чанаї`};var u={en:`Roti Canai is a dish from Malaysia prepared with all-purpose flour, thai yellow curry paste, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used. Serve the roti with a quick yellow-curry coconut sauce; canai traditionally requires repeatedly stretched laminated dough.`,ua:`Роті чанаї, страва кухні країни Малайзія, яку готують із таких продуктів: пшеничне борошно універсальне, жовта тайська паста карі, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Роті подається зі швидким кокосовим соусом карі; традиційне чанаї потребує багаторазового розтягування шаруватого тіста.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,500,`g`],[`water`,260,`ml`],[`table-salt`,7,`g`],[`ghee`,55,`g`]]},{en:`Rest the oiled dough, then repeatedly stretch each piece paper-thin, fold into layers and coil it loosely before flattening into roti canai.`,ua:`Дайте змащеному тісту відпочити, кілька разів розтягніть кожен шматок майже прозоро, складіть шарами, скрутіть і розпластайте в роті чанаї.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`ghee`,85,`g`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 9 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 9 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:9,i:[[`thai-yellow-curry-paste`,50,`g`],[`coconut-milk`,240,`ml`]]}];var h={slug:i,id:a,country:`MY`,region:n,servings:8,minutes:67,title:l,text:u,steps:d};export{o as country,h as default,a as id,s as minutes,n as region,r as servings,i as slug,d as steps,u as text,l as title};